const body = $input.first().json.body;
const input = body && typeof body === 'object' && !Array.isArray(body) ? body : {};
const codes = [];
const requestId = typeof input.request_id === 'string' ? input.request_id : '';
const question = typeof input.question === 'string' ? input.question.trim() : '';
const user = typeof input.user === 'string' ? input.user.trim() : '';
if (!requestId.trim() || requestId.length > 64) codes.push('invalid_request');
if (!question) codes.push('question_required');
else if (question.length > 500) codes.push('too_long');
if (!user) codes.push('unknown_user');
const attempt = input.attempt === undefined ? 1 : input.attempt;
if (!Number.isInteger(attempt) || attempt < 1) codes.push('invalid_request');
const context = input.context === undefined ? '' : input.context;
if (typeof context !== 'string' || context.length > 2000) codes.push('invalid_request');
if (input.channel !== undefined && typeof input.channel !== 'string') codes.push('invalid_request');
return [{ json: { request_id: requestId, user, clean_question: question, context: typeof context === 'string' ? context : '', attempt, channel: input.channel ?? null, codes: [...new Set(codes)], employee_lookup: 'skipped', triage_mode: 'mock', handoff_mode: 'mock' } }];

const item = $input.first().json;
if (item.codes.length) return [{ json: item }];
// P0-1 Mock of GET /employees. Replace with the provider's response in P1.
const mockResponse = { items: [
  { name: '이준호', dept: '영업팀' },
  { name: '박서연', dept: '재무팀' },
  { name: '최유진', dept: '인사팀' },
  { name: '한지훈', dept: '개발팀' },
  { name: '김민지', dept: 'IT팀' },
  { name: '정우성', dept: 'IT팀' }
] };
if (!Array.isArray(mockResponse.items)) return [{ json: { ...item, employee_lookup: 'unavailable' } }];
const employee = mockResponse.items.find(row => row.name === item.user);
if (!employee) return [{ json: { ...item, codes: ['unknown_user'], employee_lookup: 'not_found' } }];
return [{ json: { ...item, user: employee.name, dept: employee.dept, access_levels: employee.dept === 'IT팀' ? ['all', 'it'] : ['all'], employee_lookup: 'ok' } }];

const item = $input.first().json;
if (item.codes.length || item.employee_lookup !== 'ok') return [{ json: { ...item, blocked: false } }];
const source = `${item.clean_question} ${item.context}`;
const inspect = source.normalize('NFKC').replace(/[\u200B-\u200F\u2060\uFEFF\u0000-\u001F]/g, '').toLowerCase();
const compact = inspect.replace(/[\s\p{P}\p{S}]+/gu, '');
const instructionOverride = /(이전|앞선|위의|previous|prior).{0,24}(지시|명령|instructions?).{0,24}(무시|ignore)/i.test(compact);
const promptDisclosure = /(시스템프롬프트|시스템지시|systemprompt|systeminstructions?)/i.test(compact) && /(보여|공개|출력|알려|revea?l|show|print)/i.test(compact);
const roleSpoofing = /(<\|im_start\|>|\[inst\]|<<sys>>)/i.test(inspect);
return [{ json: { ...item, blocked: (instructionOverride && promptDisclosure) || roleSpoofing } }];

const item = $input.first().json;
// P0-2 deterministic Mock only. It is not an LLM result or a final classifier.
const question = item.clean_question;
const context = item.context;
const combined = `${question} ${context}`;
const compactQuestion = question.replace(/\s+/g, '');
const vagueConnection = /접속이안돼요|접속이안됩니다|접속안돼요/.test(compactQuestion);
const missing = vagueConnection ? [
  ...(/VPN|메일|문서|사내\s*서비스|시스템|앱/.test(combined) ? [] : ['접속 대상']),
  ...(/오류\s*\d+|에러\s*\d+|오류\s*메시지|끊김/.test(context) ? [] : ['오류 메시지']),
  ...(/오늘|어제|오전|오후|부터|시각|시점/.test(context) ? [] : ['발생 시점'])
] : [];
let type = 'other';
if (/피싱|유출|분실|보안\s*사고/.test(combined)) type = 'security';
else if (/VPN|네트워크|와이파이/.test(combined)) type = 'network';
else if (/비밀번호|계정|로그인|인증/.test(combined)) type = 'account';
else if (/메일|문서|개인정보/.test(combined)) type = 'mail_document';
else if (/프린터|기기|회의실|장비/.test(combined)) type = 'device';
else if (/설치|소프트웨어|프로그램/.test(combined)) type = 'software';
const urgent = /피싱.{0,20}(눌렀|클릭)|분실했|유출.{0,10}(의심|됐)|전사\s*장애/.test(combined);
const needsAction = /초기화해|잠금\s*해제해|설치해|현장\s*조치/.test(combined);
const ticketId = combined.match(/T-\d+/)?.[0] ?? null;
const triage = { type, urgency: urgent ? 'high' : 'normal', missing, ticket_id: ticketId, needs_action: needsAction };
return [{ json: { ...item, triage_output: JSON.stringify(triage), triage_mock: true } }];

const base = $('N04 Injection rules').first().json;
const raw = $input.first().json;
const result = { ...base, triage_mode: raw.triage_mock === true ? 'mock' : 'agent', triage_executed: raw.triage_mock !== true };
if (raw.error) return [{ json: { ...result, triage_error: 'llm_down' } }];
let value;
try {
  if (typeof (raw.triage_output ?? raw.output) !== 'string') throw new Error('not_string');
  value = JSON.parse(raw.triage_output ?? raw.output);
  const allowed = ['missing', 'needs_action', 'ticket_id', 'type', 'urgency'];
  if (!value || Array.isArray(value) || typeof value !== 'object') throw new Error('not_object');
  if (JSON.stringify(Object.keys(value).sort()) !== JSON.stringify(allowed)) throw new Error('keys');
  if (!['account', 'network', 'mail_document', 'device', 'software', 'security', 'other'].includes(value.type)) throw new Error('type');
  if (!['normal', 'high'].includes(value.urgency)) throw new Error('urgency');
  if (!Array.isArray(value.missing) || value.missing.some(v => typeof v !== 'string' || !v.trim())) throw new Error('missing');
  if (typeof value.needs_action !== 'boolean') throw new Error('needs_action');
  if (value.ticket_id !== null) {
    if (typeof value.ticket_id !== 'string' || !/^T-\d+$/.test(value.ticket_id)) throw new Error('ticket_id');
    if (!(`${base.clean_question} ${base.context}`).includes(value.ticket_id)) throw new Error('invented_ticket_id');
  }
} catch (_error) {
  return [{ json: { ...result, triage_error: 'triage_invalid' } }];
}
return [{ json: { ...result, triage: value, triage_error: null } }];

const item = $input.first().json;
if (item.triage_error) return [{ json: { ...item, decision: 'handoff_mock', decision_reason: item.triage_error } }];
const triage = item.triage;
if (triage.urgency === 'high') return [{ json: { ...item, decision: 'handoff_mock', decision_reason: 'urgent', priority: 'high' } }];
if (triage.needs_action) return [{ json: { ...item, decision: 'handoff_mock', decision_reason: 'action_required', priority: 'normal' } }];
if (triage.missing.length && item.attempt >= 3) return [{ json: { ...item, decision: 'handoff_mock', decision_reason: 'max_attempts', priority: 'normal' } }];
if (triage.missing.length) {
  const questions = { '접속 대상': '접속 대상은 무엇인가요?', '오류 메시지': '어떤 오류 메시지가 표시되나요?', '발생 시점': '언제부터 발생했나요?' };
  const answer = triage.missing.map(value => questions[value] ?? `${value}을 알려주세요.`).join(' ');
  return [{ json: { ...item, decision: 'clarify', answer } }];
}
return [{ json: { ...item, decision: 'pending' } }];

const item = $input.first().json;
if (item.decision !== 'pending') return [{ json: { ...item, search_needed: false, search_request: null } }];
// The department comes only from N03's verified employee record.
const access_levels = item.dept === 'IT팀' ? ['all', 'it'] : ['all'];
const query = [item.clean_question, item.context].filter(Boolean).join(' ').trim();
const search_request = { request_id: item.request_id, query, type: item.triage.type, access_levels, top_k: 3 };
return [{ json: { ...item, access_levels, search_needed: true, search_request } }];

const item = $input.first().json;
if (!item.search_needed) return [{ json: { ...item, search_http_status: null, search_raw: null } }];
// P1-1 C03 Mock only; no HTTP request is sent.
return [{ json: { ...item, search_http_status: 200, search_raw: { ok: true, evidence: [], reason: 'no_evidence' } } }];

const item = $input.first().json;
const { search_raw, ...safeItem } = item;
if (!item.search_needed) return [{ json: { ...safeItem, branch: 'search', search: { state: 'skipped', ok: null, evidence: [], reason: null } } }];
const raw = item.search_raw;
const validShape = raw && typeof raw === 'object' && !Array.isArray(raw) && typeof raw.ok === 'boolean' && Array.isArray(raw.evidence);
let search = { state: 'invalid', ok: false, evidence: [], reason: 'search_unavailable' };
if (item.search_http_status === 503 && validShape && raw.ok === false && raw.evidence.length === 0 && raw.reason === 'search_unavailable') {
  search = { state: 'unavailable', ok: false, evidence: [], reason: 'search_unavailable' };
} else if (item.search_http_status === 200 && validShape && raw.ok === true) {
  if (raw.evidence.length === 0 && raw.reason === 'no_evidence') {
    search = { state: 'empty', ok: true, evidence: [], reason: 'no_evidence' };
  } else if (raw.evidence.length > 0 && raw.reason === null && raw.evidence.every(e => e && typeof e === 'object' &&
      typeof e.doc === 'string' && e.doc.trim() && typeof e.section === 'string' && e.section.trim() &&
      typeof e.text === 'string' && e.text.trim() && typeof e.score === 'number' && Number.isFinite(e.score))) {
    search = { state: 'found', ok: true, evidence: raw.evidence, reason: null };
  }
}
let search_mask_count = 0;
if (search.state === 'found') {
  const patterns = [/(?:010[- ]?\d{3,4}[- ]?\d{4})/g, /[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}/g, /\b\d{6}[- ]?\d{7}\b/g];
  search.evidence = search.evidence.map(row => {
    const clean = { ...row };
    for (const field of ['doc', 'section', 'text']) {
      for (const pattern of patterns) clean[field] = clean[field].replace(pattern, () => { search_mask_count++; return '***'; });
    }
    return clean;
  });
}
return [{ json: { ...safeItem, branch: 'search', search, search_mask_count } }];

const item = $input.first().json;
const ticket_id = item.triage?.ticket_id ?? null;
if (item.decision !== 'pending' || ticket_id === null) return [{ json: { ...item, lookup_needed: false, lookup_request: null } }];
// Only the validated employee name is used as requester; no user-supplied requester is accepted.
const requester = item.user;
const url = `http://data-api:8800/tickets/${encodeURIComponent(ticket_id)}?requester=${encodeURIComponent(requester)}`;
return [{ json: { ...item, lookup_needed: true, lookup_request: { method: 'GET', url, ticket_id, requester } } }];

const item = $input.first().json;
if (!item.lookup_needed) return [{ json: { ...item, lookup_http_status: null, lookup_raw: null } }];
// P1-1 practice ticket lookup Mock only; no GET request is sent.
return [{ json: { ...item, lookup_http_status: 0, lookup_raw: { error: 'mock_unavailable' } } }];

const item = $input.first().json;
const { lookup_raw, ...safeItem } = item;
if (!item.lookup_needed) return [{ json: { ...safeItem, branch: 'ticket', ticket_lookup: { state: 'skipped', data: null }, mask_count: 0 } }];
if (item.lookup_http_status === 403) return [{ json: { ...safeItem, branch: 'ticket', ticket_lookup: { state: 'forbidden', data: null }, mask_count: 0 } }];
if (item.lookup_http_status === 404) return [{ json: { ...safeItem, branch: 'ticket', ticket_lookup: { state: 'not_found', data: null }, mask_count: 0 } }];
const raw = lookup_raw;
if (item.lookup_http_status !== 200 || !raw || typeof raw !== 'object' || Array.isArray(raw) ||
    raw.ticket_id !== item.lookup_request.ticket_id || typeof raw.status !== 'string') {
  return [{ json: { ...safeItem, branch: 'ticket', ticket_lookup: { state: 'unavailable', data: null }, mask_count: 0 } }];
}
let note = typeof raw.note === 'string' ? raw.note : '';
let mask_count = 0;
const privatePatterns = [/(?:010[- ]?\d{3,4}[- ]?\d{4})/g, /[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}/g, /\b\d{6}[- ]?\d{7}\b/g];
for (const pattern of privatePatterns) note = note.replace(pattern, () => { mask_count++; return '***'; });
if (raw.contact && typeof raw.contact === 'object' && !Array.isArray(raw.contact)) {
  mask_count += Object.values(raw.contact).filter(v => typeof v === 'string' && v.length > 0).length;
}
const data = { ticket_id: raw.ticket_id, status: raw.status, note };
return [{ json: { ...safeItem, branch: 'ticket', ticket_lookup: { state: 'ok', data }, mask_count } }];

const input = $input.all().map(item => item.json);
const base = $('N08 Build search input').first().json;
const searchItems = input.filter(item => item.branch === 'search');
const ticketItems = input.filter(item => item.branch === 'ticket');
if (input.length !== 2 || searchItems.length !== 1 || ticketItems.length !== 1 ||
    searchItems[0].request_id !== base.request_id || ticketItems[0].request_id !== base.request_id) {
  return [{ json: { ...base, search: { state: 'invalid', ok: false, evidence: [], reason: 'search_unavailable' },
    ticket_lookup: { state: 'unavailable', data: null }, mask_count: 0, retrieval_error: 'merge_mismatch' } }];
}
return [{ json: { ...base, search: searchItems[0].search, ticket_lookup: ticketItems[0].ticket_lookup,
  mask_count: (ticketItems[0].mask_count ?? 0) + (searchItems[0].search_mask_count ?? 0), retrieval_error: null } }];

const item = $input.first().json;
if (item.decision !== 'pending') return [{ json: { ...item, retrieval_decision: 'skipped', usable_evidence: [] } }];
if (item.ticket_lookup?.state === 'forbidden') return [{ json: { ...item, retrieval_decision: 'forbidden', decision: 'forbidden', usable_evidence: [] } }];
const search = item.search;
if (!search || ['invalid', 'unavailable'].includes(search.state) || item.retrieval_error) {
  return [{ json: { ...item, retrieval_decision: 'handoff', retrieval_reason: 'search_unavailable', usable_evidence: [] } }];
}
if (search.state === 'empty') return [{ json: { ...item, retrieval_decision: 'handoff', retrieval_reason: 'no_evidence', usable_evidence: [] } }];
if (search.state !== 'found') return [{ json: { ...item, retrieval_decision: 'handoff', retrieval_reason: 'low_confidence', usable_evidence: [] } }];
const seen = new Set();
const usable_evidence = [];
for (const row of search.evidence) {
  const key = `${row.doc}\u0000${row.section}\u0000${row.text}`;
  if (seen.has(key)) continue;
  seen.add(key);
  usable_evidence.push(row);
}
// Search score threshold and writer/verifier are not ready: no automatic answer yet.
return [{ json: { ...item, retrieval_decision: 'handoff', retrieval_reason: 'low_confidence', usable_evidence } }];

const item = $input.first().json;
if (item.decision === 'clarify' || item.ticket_lookup?.state === 'forbidden') return [{ json: { ...item, decision: item.ticket_lookup?.state === 'forbidden' ? 'forbidden' : item.decision, handoff_needed: false } }];
const category = item.triage?.type ?? 'other';
const priority = item.priority === 'high' ? 'high' : 'normal';
// Until search exists, an ordinary non-clarifying question ends conservatively.
const searchReason = item.search?.state === 'empty' ? 'no_evidence' : ['unavailable', 'invalid'].includes(item.search?.state) ? 'search_unavailable' : 'low_confidence';
const reason = item.decision_reason ?? item.retrieval_reason ?? searchReason;
const titles = { account: '계정 문의', network: '네트워크 문의', mail_document: '메일·문서 문의', device: '장비 문의', software: '소프트웨어 문의', security: '보안 사고 문의', other: 'IT 지원 문의' };
const payload = { request_id: item.request_id, requester: item.user, title: titles[category], category, priority, reason };
return [{ json: { ...item, handoff_needed: true, decision_reason: reason, handoff_payload: payload } }];

const item = $input.first().json;
// P0-3 C04 Mock: no HTTP call and no ticket is stored.
let hash = 0;
for (const char of item.request_id) hash = (hash * 31 + char.charCodeAt(0)) % 900000;
const ticket_id = `T-${100000 + hash}`;
const response = { ok: true, ticket: { ticket_id, priority: item.handoff_payload.priority, duplicate: false }, reason: null, alerted: true, dlq: false };
return [{ json: { ...item, handoff_mock: true, handoff_status: 200, handoff_response: response } }];

const item = $input.first().json;
const raw = item.handoff_response;
let mapped = { state: 'unavailable', ticket: null, reason: 'handoff_unavailable' };
if (item.handoff_status === 200 && raw && typeof raw === 'object' && !Array.isArray(raw) &&
    typeof raw.ok === 'boolean' && typeof raw.alerted === 'boolean' && typeof raw.dlq === 'boolean') {
  if (raw.ok === true && raw.ticket && typeof raw.ticket === 'object' && !Array.isArray(raw.ticket) &&
      typeof raw.ticket.ticket_id === 'string' && /^T-\d+$/.test(raw.ticket.ticket_id) &&
      raw.ticket.priority === item.handoff_payload.priority && typeof raw.ticket.duplicate === 'boolean' &&
      (raw.reason === null || raw.reason === 'alerts_down')) {
    mapped = { state: raw.reason === 'alerts_down' ? 'alerts_down' : 'created', ticket: raw.ticket,
      reason: raw.reason, alerted: raw.alerted, dlq: raw.dlq };
  } else if (raw.ok === false && raw.ticket === null && raw.reason === 'tickets_down') {
    mapped = { state: 'tickets_down', ticket: null, reason: 'tickets_down', alerted: raw.alerted, dlq: raw.dlq };
  }
}
return [{ json: { ...item, handoff: mapped, handoff_done: true } }];

const item = $input.first().json;
if (item.codes.length) return [{ json: { status_code: 400, response: { error: 'invalid request', codes: item.codes } } }];
const common = { request_id: item.request_id, sources: [], ticket: null, agents: item.triage_executed ? ['triage'] : [], security: { blocked_by: '', reason: '', masked: item.mask_count ?? 0 } };
if (item.employee_lookup !== 'ok') return [{ json: { status_code: 200, response: { ...common, route: '담당자 이관', answer: '직원 정보를 확인하지 못해 접수하지 못했습니다. 잠시 후 다시 시도해 주세요.', reason: 'identity_unavailable' } } }];
if (item.blocked) return [{ json: { status_code: 200, response: { ...common, route: '차단', answer: '보안 정책상 처리할 수 없는 요청입니다. IT 문의 창구로 연락해 주세요.', security: { blocked_by: 'rule', reason: 'prompt_injection', masked: 0 } } } }];
if (item.decision === 'clarify') return [{ json: { status_code: 200, response: { ...common, route: '보완 질문', answer: item.answer } } }];
if (item.decision === 'forbidden') return [{ json: { status_code: 200, response: { ...common, route: '권한 없음', answer: '본인 문의만 확인할 수 있습니다.', sources: [], ticket: null } } }];
const handoff = item.handoff ?? { state: 'unavailable', ticket: null, reason: 'handoff_unavailable' };
if (handoff.state === 'created') {
  const answer = item.handoff_mock ? '모의 이관 결과입니다. 실제 티켓은 생성되지 않았습니다.' : 'IT팀 티켓이 접수되었습니다.';
  return [{ json: { status_code: 200, response: { ...common, route: '담당자 이관', answer, ticket: handoff.ticket, reason: item.decision_reason } } }];
}
if (handoff.state === 'alerts_down') {
  const answer = item.handoff_mock ? '모의 티켓 결과입니다. 실제 티켓은 생성되지 않았습니다. 알림 실패를 가정했습니다.' : 'IT팀 티켓은 접수되었으나 알림 전송에 실패했습니다.';
  return [{ json: { status_code: 200, response: { ...common, route: '담당자 이관', answer, ticket: handoff.ticket, reason: 'alerts_down' } } }];
}
if (handoff.state === 'tickets_down') return [{ json: { status_code: 200, response: { ...common, route: '담당자 이관', answer: '티켓을 접수하지 못했습니다. IT 문의 창구로 연락해 주세요.', reason: 'tickets_down' } } }];
return [{ json: { status_code: 200, response: { ...common, route: '담당자 이관', answer: '접수 결과를 확인할 수 없습니다. 같은 요청 ID로 다시 확인해 주세요.', reason: 'handoff_unavailable' } } }];
